package dataset

import java.io.File

import org.apache.commons.io.FileUtils.{deleteQuietly, moveDirectoryToDirectory, moveFileToDirectory}

/**
 * One-deep undo for raw uploads. A new raw file supersedes the source,
 * processed output and SIPs derived from the previous one; instead of
 * deleting those they are parked in a single archive directory, which the
 * next upload replaces.
 */
object UploadArchive {

  val DIR = "previous-upload"

  // tree/ is not kept: it is regenerated by the next analysis
  private val MOVED = Seq("raw", "source", "sourceTree", "processed")
  private val SIPS = "org-sips"

  def archiveDir(rootDir: File) = new File(rootDir, DIR)

  def archive(rootDir: File, sipFiles: Seq[File]): Unit = {
    val archive = archiveDir(rootDir)
    deleteQuietly(archive)
    MOVED.map(new File(rootDir, _)).filter(_.exists()).foreach(moveDirectoryToDirectory(_, archive, true))
    sipFiles.foreach(moveFileToDirectory(_, new File(archive, SIPS), true))
  }

  /** @return false when there is no archived upload */
  def restore(rootDir: File, currentSipFiles: Seq[File], orgSipsDir: File): Boolean = {
    val archive = archiveDir(rootDir)
    if (!archive.isDirectory) false
    else {
      (MOVED :+ "tree").foreach(name => deleteQuietly(new File(rootDir, name)))
      currentSipFiles.foreach(deleteQuietly)
      MOVED.map(new File(archive, _)).filter(_.exists()).foreach(moveDirectoryToDirectory(_, rootDir, false))
      Option(new File(archive, SIPS).listFiles()).getOrElse(Array.empty[File])
        .foreach(moveFileToDirectory(_, orgSipsDir, false))
      deleteQuietly(archive)
      true
    }
  }
}
